<?php

namespace App\Console\Commands;

use App\Jobs\GenerateBibsJob;
use App\Services\BibService;
use Illuminate\Console\Command;

/**
 * Delete the zips left behind by finished e-BIB batches.
 *
 * Twin of `id-cards:prune`, and it exists for the same reason: every other
 * generated file in this system is reachable from a row, so MediaCleanupService
 * can find it by walking the tables that are about to be deleted. A batch zip
 * has no row at all — the batch lives in the cache for a day and then is simply
 * gone — which means nothing ever names its key again and no existing sweep
 * will ever see it. Without this command the bucket grows by one zip per
 * generate, forever.
 *
 * The cutoff is `GenerateBibsJob::TTL_HOURS`, not a number of its own: the
 * cache entry the download endpoint reads expires on exactly that clock, so an
 * object older than it is already undownloadable. Reading the constant keeps
 * the two from drifting apart into either dead objects or dead links.
 *
 * It sweeps BATCH_PREFIX and only BATCH_PREFIX. The per-runner PNGs under
 * BibService::PRINT_PREFIX are generated by the same job on the same disk and
 * are just as old, but `race_entries.bib_png_key` names each one and the runner
 * downloads it from their own proof page — deleting one takes away the sheet
 * somebody is carrying to the start line. Those are swept by
 * MediaCleanupService when the event itself goes.
 */
class PruneBibBatches extends Command
{
    protected $signature = 'bibs:prune {--hours=}';

    protected $description = 'Hapus zip e-BIB yang sudah lewat masa unduh (batch-nya sendiri sudah kedaluwarsa di cache).';

    public function handle(BibService $bibs): int
    {
        $hours = max((int) ($this->option('hours') ?: GenerateBibsJob::TTL_HOURS), 1);
        $cutoff = now()->subHours($hours)->getTimestamp();

        // Through the service, not Storage::disk('r2'): it is the one place that
        // decides whether a batch lives on R2 or on the local `public` disk, and
        // a second reader of that rule would eventually sweep the wrong bucket.
        $disk = $bibs->storage();
        $deleted = 0;

        foreach ($disk->files(BibService::BATCH_PREFIX) as $key) {
            // lastModified() is a remote call per object on S3, so it is asked
            // only about files that are candidates by name. Belt and braces
            // anyway: zip() is the only writer under this prefix, and this loop
            // ends in a delete.
            if (! str_ends_with($key, '.zip')) {
                continue;
            }

            if ($disk->lastModified($key) >= $cutoff) {
                continue;
            }

            $disk->delete($key);
            $deleted++;
        }

        $this->info("{$deleted} zip e-BIB lebih tua dari {$hours} jam dihapus.");

        return self::SUCCESS;
    }
}
